<?php session_start();require 'conectare.php';$rows=$pdo->query('SELECT c.titlu,COALESCE(SUM(v.nr_buc),0) bucati FROM carti c LEFT JOIN vanzari v ON v.id_carte=c.id_carte GROUP BY c.id_carte,c.titlu ORDER BY bucati DESC,c.titlu')->fetchAll();include 'page_top.php';include 'meniu.php';?><td valign="top"><h1>Statistici vanzari</h1><table border="1" cellpadding="5"><tr><th>Carte</th><th>Bucati vandute</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['titlu'])?></td><td align="right"><?=(int)$r['bucati']?></td></tr><?php endforeach;?></table></td><?php include 'page_bottom.php';?>
